import pandas as pd,numpy as np
from scipy.signal import lfilter
from scipy.optimize import least_squares
dec=4
def load(f):
    d=pd.read_csv(f)
    return dict(t=d.time_s.values[::dec],V=d.voltage_pu.values[::dec],Vs=d.voltage_setpoint_pu.values[::dec],Q=d.reactive_power_pu.values[::dec],name=f)
files=['train/A_vref_op1.csv','train/A_vref_op3.csv','train/A_amb_op1.csv','train/A_amb_op2.csv','train/A_gentrip_op1.csv','train/A_load_op2.csv']
D=[load(f) for f in files]
def lag(x,T,dt,x0):
    # Euler: y[k+1]=y[k]+dt/T*(x[k]-y[k]); y[0]=x0
    a=dt/T
    y=lfilter([a],[1,-(1-a)],x[:-1],zi=[(1-a)*x0])[0]
    return np.concatenate([[x0],y])
def simQ(p,d):
    a,b,Tq,Tv=p
    t,V,Vs,Q=d['t'],d['V'],d['Vs'],d['Q']
    dt=t[1]-t[0]; V0=V[0]
    xv=lag(V,Tv,dt,V0)
    tgt=Q[0]+a*(Vs-V0)+b*(xv-V0)
    return lag(tgt,Tq,dt,Q[0])
def res(p): return np.concatenate([simQ(p,d)-d['Q'] for d in D])
for x0 in [[2,-2,0.05,0.01],[3,2,0.1,0.02],[1,1,0.5,0.1]]:
    s=least_squares(res,x0,bounds=([-100,-100,1e-3,1e-4],[100,100,10,2]))
    print(s.x.round(4),np.sqrt(np.mean(s.fun**2)))
    for d in D: print('  ',d['name'],np.sqrt(np.mean((simQ(s.x,d)-d['Q'])**2)).round(5))

