    return dict(V=d.voltage_pu.values,Vs=d.voltage_setpoint_pu.values,P=d.active_power_pu.values,Q=d.reactive_power_pu.values,dt=0.001)
def regs(d,T):
    V,Vs,P,Q=d['V'],d['Vs'],d['P'],d['Q']
    dt=d['dt']
    # deviations from t=0 values; target Qf = lag(Q0 + a*dVs + b*dV + c*dP)
    Xs=[lagf(Vs-Vs[0],T,dt),lagf(V-V[0],T,dt),lagf(P-P[0],T,dt)]
    return np.column_stack(Xs)
def fit(T,files):
    Xs=[];ys=[]
    for f in files:
        d=data(f)
        X=regs(d,T); y=d['Q']-d['Q'][0]
        # Qf dev = lag(target dev) ; y = Qdev. Use y as target via regressors being lag'd dev signals
        Xs.append(X);ys.append(y)
    X=np.vstack(Xs);y=np.concatenate(ys)
    c=np.linalg.lstsq(X,y,rcond=None)[0]
    return c, np.sqrt(np.mean((X@c-y)**2))
